            (4966, 6, 'ev-mobilya/ev/ev-tekstili/yatak-odasi-tekstili/yorgan/battal-boy-yorgan', 'ev-mobilya-ev-ev-tekstili-yatak-odasi-tekstili-yorgan-battal-boy-yorgan', NULL),
