            (4969, 6, 'ev-mobilya/ev/ev-tekstili/yatak-odasi-tekstili/uyku-seti/battal-boy-uyku-seti', 'ev-mobilya-ev-ev-tekstili-yatak-odasi-tekstili-uyku-seti-battal-boy-uyku-seti', NULL),
            (4970, 6, 'ev-mobilya/ev/ev-tekstili/yatak-odasi-tekstili/pike-pike-takimi/battal-boy-pike-takimi', 'ev-mobilya-ev-ev-tekstili-yatak-odasi-tekstili-pike-pike-takimi-battal-boy-pike-takimi', NULL),
            (4971, 6, 'ev-mobilya/ev/ev-tekstili/yatak-odasi-tekstili/carsaf-carsaf-takimi/battal-boy-carsaf-takimi', 'ev-mobilya-ev-ev-tekstili-yatak-odasi-tekstili-carsaf-carsaf-takimi-battal-boy-carsaf-takimi', NULL),
            (5213, 6, 'supermarket/saglik/genel-saglik/bant-ve-isitici-urunler/yanik-urunleri/yanik-kremi', 'supermarket-saglik-genel-saglik-bant-ve-isitici-urunler-yanik-urunleri-yanik-kremi', NULL),
            (5214, 6, 'supermarket/saglik/genel-saglik/bant-ve-isitici-urunler/yanik-urunleri/yanik-ortusu', 'supermarket-saglik-genel-saglik-bant-ve-isitici-urunler-yanik-urunleri-yanik-ortusu', NULL),
            (5606, 6, 'ev-mobilya/ev/ev-tekstili/yatak-odasi-tekstili/battaniye/giyilebilir-battaniye', 'ev-mobilya-ev-ev-tekstili-yatak-odasi-tekstili-battaniye-giyilebilir-battaniye', NULL),
            (5607, 6, 'ev-mobilya/ev/ev-tekstili/yatak-odasi-tekstili/battaniye/elektrikli-battaniye', 'ev-mobilya-ev-ev-tekstili-yatak-odasi-tekstili-battaniye-elektrikli-battaniye', NULL)
          ) AS t(ext_id, depth, path, slug, match_name)
          JOIN external_category ec ON ec.source = 'trendyol' AND ec.external_id = t.ext_id
         ORDER BY t.depth, t.ext_id
    LOOP
        IF EXISTS (SELECT 1 FROM external_category_map
                    WHERE source = 'trendyol' AND external_id = node.ext_id) THEN
            n_skip := n_skip + 1;
            CONTINUE;
        END IF;

        IF node.match_name IS NOT NULL THEN
            SELECT id INTO cat_id FROM category
             WHERE path = node.path AND name = node.match_name ORDER BY id LIMIT 1;
            IF cat_id IS NULL THEN
                RAISE NOTICE '0102: atlandi, eslesecek mevcut dugum yok ya da adi farkli: % (%)',
                    node.path, node.match_name;
                n_bad := n_bad + 1;
                CONTINUE;
            END IF;
            INSERT INTO external_category_map
                (source, external_id, category_id, status, decided_by, note)
            VALUES ('trendyol', node.ext_id, cat_id, 'confirmed', 'migration:0102', 'exact_name');
            n_match := n_match + 1;
        ELSE
            parent_cat := NULL;
            IF node.parent_external_id IS NOT NULL THEN
                SELECT m.category_id, c.path INTO parent_cat, parent_path
                  FROM external_category_map m JOIN category c ON c.id = m.category_id
                 WHERE m.source = 'trendyol' AND m.external_id = node.parent_external_id;
                IF parent_cat IS NULL THEN
                    RAISE NOTICE '0102: atlandi, ebeveyn eslesmesi yok: % (ebeveyn %)',
                        node.ext_id, node.parent_external_id;
                    n_bad := n_bad + 1;
                    CONTINUE;
                END IF;
                IF regexp_replace(node.path, '/[^/]+$', '') <> parent_path THEN
                    RAISE NOTICE '0102: atlandi, yol ebeveynle tutarsiz: % (ebeveyn yolu %)',
                        node.path, parent_path;
                    n_bad := n_bad + 1;
                    CONTINUE;
                END IF;
            ELSIF position('/' IN node.path) > 0 THEN
                RAISE NOTICE '0102: atlandi, kok dugum yolu bilesik: %', node.path;
                n_bad := n_bad + 1;
                CONTINUE;
            END IF;
            IF EXISTS (SELECT 1 FROM category WHERE path = node.path) THEN
                RAISE NOTICE '0102: atlandi, yol zaten var (uydurma eslesme yapilmaz): %', node.path;
                n_bad := n_bad + 1;
                CONTINUE;
            END IF;
            cand_slug := node.slug;
            IF EXISTS (SELECT 1 FROM category WHERE slug = cand_slug) THEN
                cand_slug := cand_slug || '-ty' || node.ext_id;
            END IF;
            INSERT INTO category (slug, name, parent_id, path, is_discoverable)
            VALUES (cand_slug, node.name, parent_cat, node.path, FALSE)
            RETURNING id INTO cat_id;
            INSERT INTO external_category_map
                (source, external_id, category_id, status, decided_by, note)
            VALUES ('trendyol', node.ext_id, cat_id, 'confirmed', 'migration:0102', 'created');
            n_create := n_create + 1;
        END IF;
    END LOOP;

    RAISE NOTICE '0102: % eslesti, % olusturuldu, % zaten islenmisti, % UYDURULMADAN atlandi',
        n_match, n_create, n_skip, n_bad;
END $$;
